    }>(`/interviews/practice/sessions?limit=50&category=${cat}`)
    if (res.success) {
      setHistorySessions(res.sessions)
      setHistoryTotal(res.total)
    }
  } catch (err) {
    console.error('Failed to load history:', err)
  } finally {
    setHistoryLoading(false)
  }
}, [historyFilter])

