          <Volume2 className="h-5 w-5 text-emerald-600 shrink-0" />
          <div>
            <p className="text-sm font-medium text-emerald-900">Speech Analysis</p>
            <p className="text-xs text-emerald-600">Pace, filler words, clarity scoring</p>
          </div>
