                <div className="text-center py-8 space-y-3">
                  <div className="animate-spin rounded-full h-10 w-10 border-3 border-primary border-t-transparent mx-auto" />
                  <p className="font-medium text-sm">Analyzing your response...</p>
                </div>
              )}
            </>
          )}

