  }

  // Start periodic body language analysis (every 20 seconds)
  function startBodyLanguageAnalysis() {
    // First analysis after 5 seconds
    setTimeout(() => analyzeRealtimeBodyLanguage(), 5000)
    // Then every 20 seconds
