        }
      }
      const combined = finalTranscript + interim
      setMockLiveTranscript(combined)
      mockLiveTranscriptRef.current = combined  // Keep ref in sync for onstop closure
    }

    recognition.onerror = (event: any) => {
      if (event.error === 'no-speech') {
